    { id = "dr-10-bear-003", ["do"] = "turnin", quest = 5925, npc = 4217, at = {1457, 35.37, 8.4}, text = "Ve al oeste hasta Darnassus y entrega a Mathrengyl, en el Enclave Cenarion (noroeste de la ciudad).", status = "unverified" },
