    { id = "dr-10-bear-012", ["do"] = "turnin", quest = 5931, npc = 4217, at = {1457, 35.37, 8.4}, text = "Entra en Darnassus por el portal de Rut'theran y entrega a Mathrengyl.", status = "unverified" },
