    { id = "dr-16-aquatic-010", ["do"] = "accept", quest = 272, npc = 11799, at = {1450, 36.52, 40.1}, text = "Coge con Tajarri la Prueba del león marino: dos mitades de colgante, una en Costa Oscura y otra en los Páramos de Poniente.", tip = "Silva Fil'naveth y otros vecinos del Claro dan pistas si les hablas.", status = "unverified", reqlevel = 16 },
